mapper.select:
SELECT t.id, t.warehouse_id, t.sku_id, t.warn_min, t.warn_max, t.remark, t.version, t.created_at, t.updated_at, w.warehouse_code, w.name AS warehouse_name, k.sku_code, k.spec_name AS sku_name, k.spec_values, p.name AS product_name FROM inventory_warning_threshold t LEFT JOIN warehouse w ON w.id = t.warehouse_id LEFT JOIN product_sku k ON k.id = t.sku_id LEFT JOIN product_spu p ON p.id = k.spu_id WHERE t.deleted = FALSE
AND t.warehouse_id = #{query.warehouseId}
AND t.sku_id = #{query.skuId}
AND k.sku_code ILIKE CONCAT('%', #{query.skuCode}, '%')
ORDER BY t.updated_at DESC, t.id DESC

SELECT t.id AS threshold_id, t.warehouse_id, t.sku_id, t.warn_min, t.warn_max, w.warehouse_code, w.name AS warehouse_name, k.sku_code, k.spec_name AS sku_name, k.spec_values, p.name AS product_name, b.unit, COALESCE(b.quantity, 0) AS quantity, COALESCE(b.reserved_quantity, 0) AS reserved_quantity, COALESCE(b.quantity, 0) - COALESCE(b.reserved_quantity, 0) AS available_quantity FROM inventory_warning_threshold t LEFT JOIN inventory_balance b ON b.warehouse_id = t.warehouse_id AND b.sku_id = t.sku_id AND b.deleted = FALSE LEFT JOIN warehouse w ON w.id = t.warehouse_id LEFT JOIN product_sku k ON k.id = t.sku_id LEFT JOIN product_spu p ON p.id = k.spu_id WHERE t.deleted = FALSE
AND t.warehouse_id = #{query.warehouseId}
AND t.sku_id = #{query.skuId}
AND k.sku_code ILIKE CONCAT('%', #{query.skuCode}, '%')
AND = #{query.status}
AND <> 'NORMAL'
ORDER BY CASE WHEN 'LOW' THEN 0 WHEN 'HIGH' THEN 1 ELSE 2 END, t.warehouse_id ASC, t.id ASC
